{"code": "# Let's re-analyze carefully
import re
from collections import defaultdict

lines = context.strip().split('\n')
data_lines = lines[1:]

# Extract user IDs and questions
user_questions = defaultdict(list)

for line in data_lines:
    if not line.strip():
        continue

    user_match = re.search(r'User:\s*(\d+)', line)
    if not user_match:
        continue
    user_id = user_match.group(1)

    question_match = re.search(r'Instance:\s*(.*?)(?=\n|$)', line)
    if not question_match:
        continue
    question = question_match.group(1).strip()

    user_questions[user_id].append(question)

# Flatten the list of questions
all_questions = []
for user_id, questions in user_questions.items():
    all_questions.extend(questions)

# Classify each question
result = semantic_map(
    instruction="Classify each question into one of the following categories: location, numeric value, description and abstract concept, abbreviation, human being, entity. Return the category for each question.",
    schema={'type': 'string', 'enum': ['location', 'numeric value', 'description and abstract concept', 'abbreviation', 'human being', 'entity']},
    items=all_questions
)

# Create a mapping from question index to label
label_map = {}
for row in result['rows']:
    item_index = row['item']
    label = row['value']
    label_map[item_index] = label

# Now group by user
user_labels = defaultdict(list)
for i, question in enumerate(all_questions):
    user_id = None
    for uid, qs in user_questions.items():
        if question in qs:
            user_id = uid
            break
    if user_id:
        user_labels[user_id].append(label_map[i])

# Count labels per user
user_label_counts = {}
for user_id, labels in user_labels.items():
    counts = defaultdict(int)
    for label in labels:
        counts[label] += 1
    user_label_counts[user_id] = dict(counts)

# Find users with exactly one description and abstract concept
users_with_one_desc_abstract = []
for user_id, counts in user_label_counts.items():
    if counts.get('description and abstract concept', 0) == 1:
        users_with_one_desc_abstract.append(user_id)

# Find users with at least one abbreviation and at least one entity
users_with_abbr_and_entity = []
for user_id, counts in user_label_counts.items():
    if counts.get('abbreviation', 0) >= 1 and counts.get('entity', 0) >= 1:
        users_with_abbr_and_entity.append(user_id)

print("Users with exactly one description and abstract concept:", len(users_with_one_desc_abstract))
print("Users with at least one abbreviation and one entity:", len(users_with_abbr_and_entity))

# Print some examples
print("\nSample users with exactly one description and abstract concept:")
for user_id in users_with_one_desc_abstract[:5]:
    print(f"User {user_id}: {user_label_counts[user_id]}")

print("\nSample users with at least one abbreviation and one entity:")
for user_id in users_with_abbr_and_entity[:5]:
    print(f"User {user_id}: {user_label_counts[user_id]}")

# Now find all pairs
pairs = []
for user1 in users_with_one_desc_abstract:
    for user2 in users_with_abbr_and_entity:
        if user1 < user2:
            pairs.append((user1, user2))
        else:
            pairs.append((user2, user1))

print("\nTotal pairs:", len(pairs))

# Verify a few pairs
print("\nVerifying a few pairs:")
for pair in pairs[:5]:
    user1, user2 = pair
    counts1 = user_label_counts[user1]
    counts2 = user_label_counts[user2]
    print(f"User {user1}: description and abstract concept = {counts1.get('description and abstract concept', 0)}")
    print(f"User {user2}: abbreviation = {counts2.get('abbreviation', 0)}, entity = {counts2.get('entity', 0)}")
"}

